pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 fund, uint256 amount, address recipient) public {
        vm.assume(recipient != address(0));
        fund = bound(fund, 1 ether, 1e30);
        amount = bound(amount, 1, fund);

        // fund c through its payable receive() so it has ether to forward
        vm.deal(address(this), fund);
        (bool okPay,) = address(c).call{value: fund}("");
        assertTrue(okPay);

        uint256 pre = address(c).balance;

        // Owner (deployer = this test contract) drives Command with the fuzzed amount
        c.Command{value: amount}(recipient, "");

        // General rule: after Command{value: v}, c's balance dropped by exactly v.
        // The mutant forwards 0 wei, so c's balance is unchanged and this fails.
        assertTrue(address(c).balance == pre - amount);
    }

    receive() external payable {}
}

