import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    RejectZero callee;

    function setUp() public {
        c = new C();
        callee = new RejectZero();
        vm.deal(address(this), type(uint256).max / 2);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        // setUp() deployer (this test contract) is Owner of c; call Command as owner
