pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 balance, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        balance = bound(balance, 1, type(uint128).max);
        vm.deal(address(c), balance);
        // value is derived from c's own public balance, not hard-coded
        uint256 value = address(c).balance;
        vm.deal(actor, value);
        bool ok;
        vm.prank(actor);
        try c.multiplicate{value: value}(actor) { ok = true; } catch { ok = false; }
        // Rule: multiplicate with msg.value >= balance attempts transfer(balance+value)
        // which exceeds the contract's funds, so it must revert.
        assertTrue(!ok);
    }
}

