pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1e30);

        // adversarial recipient that reverts on any transfer
        Reverter adr = new Reverter();

        vm.deal(actor, 2 * amount + 1);

        // fund c with exactly `amount` so address(c).balance == amount
        vm.prank(actor);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);

        // msg.value == address(c).balance here
        vm.prank(actor);
        bool ok;
        try c.multiplicate{value: amount}(address(adr)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference P always attempts the transfer of balance+msg.value to a
        // reverting recipient, so it must revert for every admissible input.
        assertTrue(!ok);
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }
    fallback() external payable {
        revert();
    }
}

