pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address adr, uint256 seed, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(adr != address(c));
        seed = bound(seed, 0, 1 ether);
        amount = bound(amount, 1, 10 ether);

        // pre-fund c so the branch condition is non-trivial
        address funder = address(0xF00D);
        vm.deal(funder, seed);
        vm.prank(funder);
        (bool s0, ) = payable(address(c)).call{value: seed}("");
        assertTrue(s0);

        uint256 balBefore = address(c).balance;
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.multiplicate{value: amount}(adr) {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: any completed multiplicate call with msg.value >= prior balance
        // drains the entire contract balance (it becomes 0).
        assertTrue(!ok || address(c).balance == 0);

        // Reference: ok implies drained. Buggy version: transfers only msg.value,
        // leaving balBefore (nonzero when seed > 0) in the contract.
        // The fuzzer will find e.g. seed > 0, amount >= seed, reachable adr.
        (void)balBefore;
    }
}

