pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint256 amount, address actor) public {
        seed = bound(seed, 1, 1 ether);
        amount = bound(amount, seed, seed + 1 ether);
        vm.assume(actor != address(0) && actor != address(c));

        // give c some pre-existing balance and the actor funds
        vm.deal(address(c), seed);
        vm.deal(actor, amount);

        // adversarial counterparty: a sink that accepts ETH (transfer target)
        Sink sink = new Sink();
        uint256 sinkBefore = address(sink).balance;

        vm.prank(actor);
        c.multiplicate{value: amount}(address(sink));

        // General rule: the callee receives exactly the contract's prior
        // balance plus msg.value; the mutant sends only msg.value.
        assertTrue(address(sink).balance - sinkBefore == seed + amount);
    }
}

contract Sink {
    receive() external payable {}
}

