        vm.assume(amount >= PRE && amount <= type(uint128).max);
        vm.deal(actor, amount);
        vm.prank(actor);
        // recipient is c itself: no external counterparty involved
        c.multiplicate{value: amount}(address(c));
        // C always pays out balance+msg.value, so c's balance returns to PRE;
        // the mutant pays out only msg.value, so c's balance grows above PRE.
        assertTrue(address(c).balance <= PRE);
    }
}

