pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 deposit) public {
        // Admissible domain: any send value; contract pre-funded with a positive balance.
        deposit = bound(deposit, 1, type(uint256).max / 2);
        amount = bound(amount, 0, type(uint256).max / 4);
        vm.deal(address(c), deposit);
        // Adversarial counterparty: accepts a payment only if it exceeds `amount`.
        Greedy recipient = new Greedy(amount);
        vm.deal(address(this), amount);
        vm.prank(address(this));
        bool ok;
        try c.multiplicate{value: amount}(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: with a positive pre-existing balance, C always pays out
        // balance+msg.value (> amount), which `recipient` accepts, so the call
        // succeeds for every admissible input. The mutant sends only `amount`,
        // which `recipient` rejects, so the call fails.
        assertTrue(ok);
    }
}

contract Greedy {
    uint256 public threshold;
    constructor(uint256 t) { threshold = t; }
    receive() external payable {
        require(msg.value > threshold);
    }
}

