        require(msg.sender != c.Owner());
        require(address(this).balance >= amount);

        // On P this reverts because access control requires msg.sender == Owner.
        // On M the require was removed, so the call succeeds.
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSelector(c.Command.selector, adr, data)
        );

        assert(!ok);
    }

    receive() external payable {}
}

